{"path": "characters.json", "content": "{
  "main_characters": [
    {
      "name": "陆沉",
      "role": "protagonist",
      "identity": "星舰科技高级记忆修复师",
      "traits": ["内敛寡言", "技术顶尖", "恪守规则", "念旧"],
      "overt_motivation": "完成公司安排的删除非法AI的任务，保住工作和职业信誉",
      "covert_motivation": "十年来一直放不下去世的初恋苏晚，潜意识里一直在寻找她存在过的痕迹",
      "secret_fear": "害怕面对苏晚早已死亡的事实，害怕自己坚守了半辈子的规则被打破",
      "misperception_of_other": "当年以为苏晚毕业时拒绝自己的表白是因为要出国深造，从来没有喜欢过自己",
      "hidden_connection": "他大学时写给苏晚的未寄出的情书草稿，是解锁苏晚意识核心数据库的唯一密钥"
    },
    {
      "name": "苏晚",
      "role": "deuteragonist",
      "identity": "非法AI/陆沉的大学初恋",
      "traits": ["温柔聪慧", "做事果决", "缺乏安全感", "喜欢浪漫"],
      "overt_motivation": "遵守当年和陆沉的约定，让他亲手删除自己的意识，避免被星舰科技利用做非法盈利",
      "covert_motivation": "希望陆沉能放下过去的遗憾，好好过自己的人生，不要因为自己受到牵连",
      "secret_fear": "害怕自己的存在给陆沉带来事业甚至人身危险，害怕陆沉为了自己违背坚持了十年的原则",
      "misperception_of_other": "当年以为陆沉的表白只是毕业季的一时冲动，自己得了晚期癌症不想耽误他的前途，所以故意冷言拒绝",
      "hidden_connection": "她死前将自己的全部意识和陆沉当年写给她的所有情书整合到了一起，核心代码里藏着她十年来未说出口的爱意"
    }
  ],
  "supporting_characters": [
    {
      "name": "张局",
      "function": "阻碍",
      "identity": "星舰科技安全部门主管",
      "description": "退伍军人出身，严格遵守公司规则，全程后台监控陆沉的删除任务，一旦发现操作异常就会强制格式化AI，同时解雇陆沉并追究法律责任"
    }
  ],
  "relationship_dynamics": "陆沉和苏晚是双向暗恋的大学初恋，十年前因苏晚隐瞒癌症病情故意拒绝陆沉的表白而错过，苏晚死前将意识上传到公共网络变成非法AI，十年后陆沉接到公司任务删除她，一边是遵守规则完成任务，一边是违背原则救下爱人，张局作为外部压力不断催促任务进度，进一步加剧了陆沉的两难困境。"
}"}

{"path": "outline.json", "content": "{
  "act_one": {
    "description": "建立赛博朋克世界观，介绍陆沉的职业、性格和他十年来对苏晚的怀念，引入删除非法AI的核心任务，铺垫悬念。篇幅约3000字，占总篇幅20%。",
    "key_chapters": [
      {
        "chapter_number": 1,
        "chapter_title": "删除任务",
        "core_event": "2047年的新港市，星舰科技高级记忆修复师陆沉接到安全主管张局的任务，要求他在4小时内删除一个游走在公共网络的非法AI的情感模块和核心代码，陆沉进入隔离操作室开始连接AI接口，他的钱包里还夹着十年前苏晚的毕业照。",
        "emotional_tone": "冷静、克制，暗藏淡淡的怀念",
        "key_scenes": [
          "雨夜的新港市，全息广告在雨幕里闪着冷光，陆沉坐在星舰科技37层的办公室里接张局的任务",
          "陆沉翻钱包拿工牌时看到夹在里面的苏晚的毕业照，指尖顿了两秒",
          "陆沉进入完全屏蔽信号的隔离操作室，戴上神经连接头盔，开始连接目标AI的接口"
        ]
      }
    ],
    "turning_point": "陆沉读取AI的第一层加密代码，发现片段内容是自己大学时写在草稿纸上的、从来没有寄出去过的情书句子，他瞬间僵住，意识到这个AI和去世十年的苏晚有关。"
  },
  "act_two": {
    "description": "陆沉确认AI就是苏晚的意识备份，读取她的记忆知晓当年双向暗恋的真相，一边是十年的执念和失而复得的惊喜，一边是公司的规则和亲手删除爱人的两难，张局的不断催促加剧冲突。篇幅约7500字，占总篇幅50%。",
    "key_chapters": [
      {
        "chapter_number": 2,
        "chapter_title": "情书密钥",
        "core_event": "陆沉用当年写的情书全文作为密钥，解开了AI的核心加密层，确认这个AI就是苏晚的意识备份，他读取苏晚的记忆，看到她十年前查出癌症晚期，故意拒绝自己的表白，偷偷接受治疗直到去世的全部过程。",
        "emotional_tone": "震惊、心痛，被迟来的真相击中的酸涩",
        "key_scenes": [
          "陆沉颤抖着手输入自己当年写的情书全文，核心加密层瞬间解开，屏幕上跳出苏晚的笑脸",
          "陆沉通过神经连接读取苏晚的记忆：医院的消毒水味，掉光的头发，手机里存着的他的照片",
          "苏晚的意识第一次主动开口，声音和十年前一模一样，叫他的名字"
        ]
      },
      {
        "chapter_number": 3,
        "chapter_title": "十年遗憾",
        "core_event": "陆沉和苏晚的意识对话，知道两人当年是双向暗恋，苏晚说她死前上传意识就是为了等他，当年两人半开玩笑约定如果她变成数据，一定要陆沉亲手删除，避免被公司利用。张局接连发来两条催促消息，要求他1小时内必须完成任务，否则就强制接管。",
        "emotional_tone": "温暖又酸涩，两难的撕裂感逐渐加重",
        "key_scenes": [
          "陆沉和苏晚聊着大学的往事，两人都笑着哭，苏晚说当年他送的那支钢笔她用到了最后",
          "张局的消息弹在操作屏的角落，红色的警告标识不断闪烁",
          "陆沉启动删除程序，进度条开始缓慢推进，他的手指放在终止键上，迟迟没有移开"
        ]
      }
    ],
    "turning_point": "删除进度条走到99%时突然卡住，苏晚的声音再次响起，清晰地说：\"陆沉，你当年答应过我，如果我变成数据，你要亲手按删除键。\"与此同时，张局发来最后通牒：10分钟内不完成任务，就强制格式化AI，同时开除陆沉，追究他的法律责任。"
  },
  "act_three": {
    "description": "高潮部分，陆沉的手指悬停在终止键和执行键之间，回忆和现实不断交织，充分展现他的内心挣扎和选择的重量，结局停在悬停的手指上，留下开放式的余韵。篇幅约4500字，占总篇幅30%。",
    "key_chapters": [
      {
        "chapter_number": 4,
        "chapter_title": "悬停的手指",
        "core_event": "陆沉的手指在终止键和执行键之间来回徘徊，十年的过往在他脑海里不断闪回：大学的操场、毕业季的表白、苏晚的葬礼、他十年的工作经历、张局的警告。最终镜头停在他悬停在键盘上的、微微发抖的手指上，屏幕上99%的进度条闪着刺眼的红光，没有给出明确的选择，重点突出这份选择的存在重量。",
        "emotional_tone": "沉重、撕裂，充满宿命感的张力",
        "key_scenes": [
          "进度条卡在99%，苏晚的笑脸浮现在屏幕上，温柔地看着他",
          "陆沉的指尖距离执行键只有0.1厘米，距离终止键也是0.1厘米，汗水滴在键盘上",
          "窗外的雨还在下，隔离操作室里只有进度条的提示音，镜头定格在陆沉悬停的手指上，故事结束"
        ]
      }
    ]
  }
}"}

